#!/usr/bin/env php
<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';
use Illuminate\Support\Facades\DB;
if(!app()->environment('testing')||!preg_match('/^classroom_integration_[a-f0-9]+$/D',DB::connection()->getDatabaseName()))throw new RuntimeException('Dedicated integration database required.');
$lesson=(int)($argv[1]??0);$row=DB::table('lessons')->where('id',$lesson)->first();if(!$row)throw new RuntimeException('Integration lesson missing.');
$sessions=[];foreach(DB::table('model_sessions')->where('lesson_id',$lesson)->orderBy('created_at')->get()as$s){$c=json_decode($s->config,true,64,JSON_THROW_ON_ERROR);$sessions[]=['id'=>$s->id,'purpose'=>$c['purpose']??null,'epoch'=>$c['epoch']??null,'base_sample'=>(int)$s->base_sample,'sent_samples'=>isset($c['sent_samples'])?(int)$c['sent_samples']:null,'sent_samples_complete'=>$c['sent_samples_complete']??false,'status'=>$s->status,'created_at'=>$s->created_at,'ended_at'=>$s->ended_at,'approximate_boundary'=>$c['approximate_boundary']??false];}
$stats=DB::table('audio_segments')->where('lesson_id',$lesson)->selectRaw('count(*) n,sum(sample_count) samples,min(start_sample) first,max(start_sample+sample_count) last,count(DISTINCT epoch) epochs')->first();
$gap=DB::selectOne('SELECT count(*) n FROM (SELECT start_sample,lag(start_sample+sample_count) OVER(ORDER BY start_sample,id) previous_end FROM audio_segments WHERE lesson_id=?) q WHERE previous_end IS NOT NULL AND start_sample<>previous_end',[$lesson]);
$counts=DB::table('subtitle_units')->where('lesson_id',$lesson)->selectRaw('kind,status,count(*) n')->groupBy('kind','status')->orderBy('kind')->orderBy('status')->get();
$usage=[];foreach(DB::table('usage_records')->where('lesson_id',$lesson)->orderBy('id')->get()as$u)$usage[]=['model_session_id'=>$u->model_session_id,'response_id'=>$u->response_id,'status'=>$u->status,'official'=>$u->official,'usage'=>json_decode($u->usage,true,64,JSON_THROW_ON_ERROR)];
$rotations=[];foreach(DB::table('lesson_events')->where('lesson_id',$lesson)->where('event_type','translation.rotation')->orderBy('seq')->get()as$e)$rotations[]=['seq'=>(int)$e->seq,'payload'=>json_decode($e->payload,true)];
$archive=DB::table('recordings')->where('lesson_id',$lesson)->first();$chunks=DB::table('audio_chunks')->where('lesson_id',$lesson)->selectRaw('storage_state,count(*) n,sum(sample_count) samples')->groupBy('storage_state')->get();
$known=count($sessions)>0&&count(array_filter($sessions,fn($s)=>$s['sent_samples']!==null&&$s['sent_samples_complete']))===count($sessions);$sent=$known?array_sum(array_column($sessions,'sent_samples')):null;
$peerCoverage=null;if($known){$expected=0;$peerCoverage=true;foreach($sessions as$s){if($s['sent_samples']===0)continue;if($s['base_sample']!==$expected)$peerCoverage=false;$expected=$s['base_sample']+$s['sent_samples'];}if($expected!==(int)$row->media_samples)$peerCoverage=false;}
$interrupted=0;foreach($counts as$c)if($c->status==='interrupted')$interrupted+=(int)$c->n;
$result=['test_kind'=>'real_model_real_oss_database_readback','lesson_id'=>$lesson,'status'=>$row->status,'translation_status'=>$row->translation_status,'media_samples'=>(int)$row->media_samples,'model_sessions'=>$sessions,'model_sent_samples'=>$sent,'no_duplicate_audio_forwarding'=>$known?$sent===(int)$row->media_samples&&$peerCoverage:null,'forwarding_counter_scope'=>'Local QwenSession sendAudio sample counts and contiguous peer bases; provider exactly-once receipt is not verified.','model_audio_peer_coverage_contiguous'=>$peerCoverage,'audio_segments'=>['count'=>(int)$stats->n,'samples'=>(int)$stats->samples,'first_sample'=>(int)$stats->first,'last_sample'=>(int)$stats->last,'epoch_count'=>(int)$stats->epochs,'gaps_or_overlaps'=>(int)$gap->n],'audio_chunks'=>$chunks,'subtitle_status_counts'=>$counts,'retained_interrupted_unit_count'=>$interrupted,'official_usage'=>$usage,'rotation_events'=>$rotations,'archive'=>$archive?['status'=>$archive->status,'samples'=>(int)$archive->duration_samples,'bytes'=>(int)$archive->bytes,'sha256'=>$archive->sha256,'object_key_sha256'=>hash('sha256',$archive->object_key)]:null,'physical_microphone_verified'=>false,'physical_device_verified'=>false,'translation_split_quality_verified'=>false];
echo json_encode($result,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR).PHP_EOL;
